"""Per-component credentials: generated by ``apply``, set on the target system, stored in Nomad.

Kafka (the only system so far): every principal in the Kafka plan gets a SCRAM-SHA-512
user with a random password. The password is stored in a Nomad Variable in the
environment's namespace:

- a component's principal (``certlog.worker``): ``nomad/jobs/<job>``, keys
  ``LEASEHOLD_KAFKA_USERNAME`` and ``LEASEHOLD_KAFKA_PASSWORD``. Nomad lets the job read
  that path without an ACL policy, and the job's template renders it into env vars.
- a service's ClickHouse sink principal (``certlog.clickhouse``):
  ``leasehold/<service>/clickhouse-kafka``, keys ``username`` and ``password``. Only
  operators read it; the ClickHouse step puts it in the named collection.

``diff`` decides per principal:

- the Kafka user and the variable both exist → nothing to do (``rotate`` forces a new
  password);
- either is missing → a new password, set in Kafka first, then written to the variable.
  Other keys in the variable are kept. Running jobs restart when the variable changes
  (template ``change_mode = restart``) and pick up the new password.

Stale, reported and removed only with ``prune``: SCRAM users of the given services that
the plan no longer has, and the Kafka keys in their component variables (the variable is
deleted when nothing else is in it). Passwords are never printed.

Nomad's state is the only copy of a password. If it's lost, ``apply --rotate`` sets new
ones everywhere; nothing else needs a backup.
"""

from __future__ import annotations

import secrets
from dataclasses import dataclass, field

from confluent_kafka.admin import (
    AdminClient,
    ScramCredentialInfo,
    ScramMechanism,
    UserScramCredentialDeletion,
    UserScramCredentialUpsertion,
)

from leasehold import naming
from leasehold.kafka.apply import TIMEOUT_S
from leasehold.nomad.apply import Nomad
from leasehold.nomad.render import job_variable_path, uses_kafka
from leasehold.spec.models import ServiceSpec

KAFKA_USER_KEY = "LEASEHOLD_KAFKA_USERNAME"
KAFKA_PASSWORD_KEY = "LEASEHOLD_KAFKA_PASSWORD"
SCRAM_ITERATIONS = 8192


@dataclass(frozen=True)
class KafkaCredential:
    principal: str  # SCRAM user, e.g. "dev.certlog.worker"
    namespace: str  # Nomad namespace of the variable
    path: str  # Nomad Variable path
    user_key: str
    password_key: str

    def __str__(self) -> str:
        return f"kafka user {self.principal} → {self.namespace}/{self.path}"


def plan(specs: list[ServiceSpec], env: str) -> list[KafkaCredential]:
    namespace = naming.nomad_namespace(env)
    out = []
    for spec in specs:
        for cname, c in spec.components.items():
            if uses_kafka(c):
                out.append(
                    KafkaCredential(
                        principal=naming.kafka_principal(env, spec.name, cname),
                        namespace=namespace,
                        path=job_variable_path(naming.nomad_job(spec.name, cname)),
                        user_key=KAFKA_USER_KEY,
                        password_key=KAFKA_PASSWORD_KEY,
                    )
                )
        if spec.clickhouse and spec.clickhouse.sinks:
            out.append(
                KafkaCredential(
                    principal=naming.clickhouse_sink_principal(env, spec.name),
                    namespace=namespace,
                    path=naming.clickhouse_kafka_variable(spec.name),
                    user_key="username",
                    password_key="password",
                )
            )
    return sorted(out, key=lambda c: c.principal)


@dataclass
class CredentialChange:
    credential: KafkaCredential
    reason: str  # "new", "kafka user missing", "variable missing", "rotate"
    _existing_items: dict[str, str] = field(default_factory=dict, repr=False)
    _modify_index: int = 0

    def __str__(self) -> str:
        return f"set      {self.credential}  ({self.reason})"


@dataclass
class CredentialDiff:
    changes: list[CredentialChange] = field(default_factory=list)
    stale_users: list[str] = field(default_factory=list)
    stale_variables: list[tuple[str, str]] = field(default_factory=list)  # (namespace, path)

    @property
    def empty(self) -> bool:
        return not self.changes


def _scram_users(admin: AdminClient) -> set[str]:
    return set(admin.describe_user_scram_credentials(request_timeout=TIMEOUT_S).result())


def diff(
    admin: AdminClient,
    nomad: Nomad,
    creds: list[KafkaCredential],
    env: str,
    services: list[str],
    rotate: bool = False,
) -> CredentialDiff:
    d = CredentialDiff()
    users = _scram_users(admin)
    for c in creds:
        var = nomad.var_get(c.path, c.namespace)
        items = dict((var or {}).get("Items") or {})
        has_var = bool(items.get(c.password_key)) and items.get(c.user_key) == c.principal
        has_user = c.principal in users
        if has_var and has_user and not rotate:
            continue
        if rotate and has_var and has_user:
            reason = "rotate"
        elif not has_var and not has_user:
            reason = "new"
        elif not has_user:
            reason = "kafka user missing"
        else:
            reason = "variable missing"
        d.changes.append(
            CredentialChange(c, reason, items, int((var or {}).get("ModifyIndex") or 0))
        )

    planned = {c.principal for c in creds}
    prefix = "" if env == naming.PROD else f"{env}."
    managed = tuple(f"{prefix}{s}." for s in services)
    d.stale_users = sorted(u for u in users if u.startswith(managed) and u not in planned)

    namespace = naming.nomad_namespace(env)
    planned_paths = {c.path for c in creds}
    for s in services:
        for path in nomad.var_list(f"nomad/jobs/{s}-", namespace):
            if path in planned_paths:
                continue
            var = nomad.var_get(path, namespace) or {}
            if KAFKA_PASSWORD_KEY in (var.get("Items") or {}):
                d.stale_variables.append((namespace, path))
    return d


def new_password() -> str:
    return secrets.token_urlsafe(32)


def apply(admin: AdminClient, nomad: Nomad, d: CredentialDiff, prune: bool = False) -> None:
    """Set each changed credential in Kafka, then in its Nomad Variable."""
    info = ScramCredentialInfo(ScramMechanism.SCRAM_SHA_512, SCRAM_ITERATIONS)
    for ch in d.changes:
        c = ch.credential
        password = new_password()
        upsert = UserScramCredentialUpsertion(c.principal, info, password.encode())
        for fut in admin.alter_user_scram_credentials([upsert], request_timeout=TIMEOUT_S).values():
            fut.result()
        items = dict(ch._existing_items) | {c.user_key: c.principal, c.password_key: password}
        nomad.var_put(c.path, c.namespace, items, ch._modify_index)
    if prune:
        if d.stale_users:
            deletions = [
                UserScramCredentialDeletion(u, ScramMechanism.SCRAM_SHA_512) for u in d.stale_users
            ]
            for fut in admin.alter_user_scram_credentials(
                deletions, request_timeout=TIMEOUT_S
            ).values():
                fut.result()
        for namespace, path in d.stale_variables:
            var = nomad.var_get(path, namespace)
            if var is None:
                continue
            items = {
                k: v
                for k, v in (var.get("Items") or {}).items()
                if k not in (KAFKA_USER_KEY, KAFKA_PASSWORD_KEY)
            }
            if items:
                nomad.var_put(path, namespace, items, int(var["ModifyIndex"]))
            else:
                nomad.var_delete(path, namespace)
